<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import 'element-plus/es/components/message-box/style/css'
import {getArticle,type AdminArticle} from '@/api/admin-articles'
import {adminQuiz,saveQuiz,quizStatus,type AdminQuiz,type QuizQuestionInput} from '@/api/quiz'
import {useFormFeedback} from '@/feedback/useFormFeedback'
import FieldError from '@/components/FieldError.vue'
import FormFeedback from '@/components/FormFeedback.vue'
import {notifySuccess} from '@/feedback/notify'
import {ApiError} from '@/api/client'
import {getAccessToken,getGeneration,onRemoteIdentityChange} from '@/auth/token-session'
import {useAuthStore} from '@/stores/auth'
import {useAuthDialogStore} from '@/stores/auth-dialog'
const auth=useAuthStore(),login=useAuthDialogStore(),sessionStale=ref(false),reauth=ref(false),editingOwner=ref(auth.user?.id)
const route=useRoute(),router=useRouter(),article=ref<AdminArticle>(),record=ref<AdminQuiz|null>(null),questions=ref<QuizQuestionInput[]>([]),baseline=ref('[]'),loading=ref(false),ready=ref(false),busy=ref(false),invalidated=ref(false),pageError=ref(''),conflict=ref(false)
const version=computed(()=>typeof route.query.version==='string'?route.query.version:article.value?.publishedVersionId||article.value?.draftVersionId||'')
const dirty=computed(()=>baseline.value!==JSON.stringify(questions.value))
const types:Record<string,string>={MAIN_IDEA:'主旨大意',DETAIL:'事实细节',INFERENCE:'推理判断',VOCABULARY:'词义猜测',ATTITUDE:'作者态度'}
const fields=['questions',...Array.from({length:10},(_,i)=>['stem','type','options','options[0]','options[1]','options[2]','options[3]','correctOption','explanation','sortOrder'].map(k=>`questions[${i}].${k}`)).flat()]
const feedback=useFormFeedback({fields,onPageError:e=>{pageError.value=e.message}}),{form,panel,fieldErrors,formError}=feedback
let ticket=0,disposed=false,controller:AbortController|undefined
function valid(t:number,identity:number){return !disposed&&ticket===t&&identity===getGeneration()&&!invalidated.value}
function settled(t:number,identity:number){if(disposed||ticket!==t||invalidated.value)return;busy.value=false;loading.value=false;if(identity!==getGeneration()){sessionStale.value=true;pageError.value='登录状态已失效，本地草稿已保留，请重新验证登录。'}}
function authenticate(){reauth.value=true;login.switchMode('login');login.request(route.fullPath)}
watch(()=>login.open,open=>{if(!open&&reauth.value&&getAccessToken()&&auth.isAdmin&&auth.user?.id===editingOwner.value){reauth.value=false;sessionStale.value=false;pageError.value='';if(!ready.value)void load()}})
function blank():QuizQuestionInput{return {key:'q_'+crypto.randomUUID().replaceAll('-',''),type:'MAIN_IDEA',stem:'',options:['','','',''],correctOption:'A',explanation:'',sortOrder:questions.value.length}}
function fill(value:AdminQuiz|null){record.value=value;questions.value=value?structuredClone(value.draft):[blank()];baseline.value=JSON.stringify(questions.value);feedback.reset();conflict.value=false}
async function leave(){if(!dirty.value||invalidated.value)return true;try{await ElMessageBox.confirm('未保存的题目修改将丢失，是否继续？','离开题组编辑',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑',autofocus:false});return true}catch{return false}}
async function load(){editingOwner.value=auth.user?.id;const t=++ticket,identity=getGeneration();controller?.abort();controller=new AbortController();loading.value=true;busy.value=false;invalidated.value=false;sessionStale.value=false;pageError.value='';article.value=undefined;ready.value=false;fill(null);try{const data=await getArticle(String(route.params.id));if(!valid(t,identity))return;article.value=data;const result=await adminQuiz(data.id,version.value,controller.signal);if(valid(t,identity)){fill(result);ready.value=true}}catch(e){if(valid(t,identity)){await feedback.fail(e);if(!pageError.value)pageError.value=formError.value||'无法加载题组，请重试。'}}finally{settled(t,identity)}}
async function reload(){const t=ticket,identity=getGeneration();if(await leave()&&!disposed&&t===ticket&&identity===getGeneration())await load()}
async function save(){if(busy.value||sessionStale.value||invalidated.value||!article.value)return;if(!feedback.validate()){await feedback.focusError();return}const t=ticket,identity=getGeneration();busy.value=true;try{const result=await saveQuiz(article.value.id,version.value,questions.value,record.value?.lockVersion??0);if(valid(t,identity)){fill(result);notifySuccess('题组草稿已保存')}}catch(e){if(valid(t,identity)){conflict.value=e instanceof ApiError&&e.code==='QUIZ_CONFLICT';await feedback.fail(e)}}finally{settled(t,identity)}}
async function status(publish:boolean){if(busy.value||sessionStale.value||dirty.value||!record.value||invalidated.value)return;const t=ticket,identity=getGeneration();busy.value=true;try{try{await ElMessageBox.confirm(publish?'确认题干、四个选项、正确答案和解析均已校对？发布将生成不可变题组版本。':'下架后不能开始新体验，已开始的体验仍使用原版本。',publish?'发布题组':'下架题组',{confirmButtonText:publish?'确认发布':'确认下架',cancelButtonText:'取消',autofocus:false})}catch{return}if(!valid(t,identity))return;const result=await quizStatus(record.value.id,publish,record.value.lockVersion);if(valid(t,identity)){fill(result);notifySuccess(publish?'题组已发布':'题组已下架')}}catch(e){if(valid(t,identity)){conflict.value=e instanceof ApiError&&e.code==='QUIZ_CONFLICT';await feedback.fail(e)}}finally{settled(t,identity)}}
function add(){if(!busy.value&&questions.value.length<10){questions.value.push(blank());feedback.reset()}}
async function remove(index:number){if(busy.value||questions.value.length<=1)return;const t=ticket,identity=getGeneration();try{await ElMessageBox.confirm('将从草稿移除此题，已发布版本保留。','移除题目',{confirmButtonText:'确认移除',cancelButtonText:'取消',autofocus:false});if(valid(t,identity)){questions.value.splice(index,1);feedback.reset()}}catch{}}
function changeVersion(event:Event){const control=event.target as HTMLSelectElement,v=control.value;control.value=version.value;void router.push({path:route.path,query:{version:v}})}
function clear(){ticket++;controller?.abort();invalidated.value=true;ready.value=false;article.value=undefined;record.value=null;questions.value=[];baseline.value='[]';busy.value=false;loading.value=false;feedback.reset();pageError.value='账户状态已变化，请重新加载题组。'}
function unloading(e:BeforeUnloadEvent){if(dirty.value&&!invalidated.value){e.preventDefault();e.returnValue=''}}
window.addEventListener('beforeunload',unloading)
const unsubscribe=onRemoteIdentityChange(clear)
watch(()=>auth.user?.id,(value,previous)=>{if(previous&&value!==previous)clear()},{flush:'sync'})
watch(()=>[route.params.id,route.query.version],load,{immediate:true});onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave);onBeforeUnmount(()=>{disposed=true;clear();unsubscribe();window.removeEventListener('beforeunload',unloading)})
</script>
<template><section class="reading-page quiz-admin"><header class="reading-page-header"><div><RouterLink class="reading-back" :to="`/admin/articles/${route.params.id}/edit`">← 返回文章编辑</RouterLink><h1>阅读题组管理</h1><p>每个文章版本一组，1—10题。保存草稿不改变当前公开题目。</p></div></header><p v-if="loading" role="status">正在加载题组…</p><div v-if="pageError" class="reading-notice" role="alert"><p>{{ pageError }}</p><button v-if="sessionStale" class="button-primary" type="button" @click="authenticate">重新验证登录</button><button class="button-secondary" :disabled="busy" @click="reload">重新加载题组管理</button></div><template v-if="!loading&&article&&ready&&!invalidated"><div class="writing-admin-version"><strong>{{ article.draft.titleZh }}</strong><label>文章版本 <select :value="version" :disabled="busy" @change="changeVersion"><option v-if="article.publishedVersionId" :value="article.publishedVersionId">当前发布版（{{ article.publishedVersionId }}）</option><option v-if="article.draftVersionId!==article.publishedVersionId" :value="article.draftVersionId">当前草稿版（{{ article.draftVersionId }}）</option><option v-if="version!==article.draftVersionId&&version!==article.publishedVersionId" :value="version">历史版本（{{ version }}）</option></select></label><span>{{ record?{DRAFT:'草稿',PUBLISHED:'已发布',UNLISTED:'已下架'}[record.status]:'尚无题组' }} · 发布 {{ record?.revision??0 }} 次</span></div><form ref="form" class="article-editor" @invalid.capture="feedback.invalid" @submit.prevent="save"><FieldError id="quiz-questions-error" :message="fieldErrors.questions"/><fieldset :disabled="busy"><section v-for="(q,i) in questions" :key="q.key" class="quiz-editor-question"><div class="quiz-editor-heading"><h2>第 {{ i+1 }} 题</h2><button type="button" class="text-button" :disabled="questions.length<=1" @click="remove(i)">移除此题</button></div><div class="quiz-editor-meta"><label>题型 <select v-model="q.type" :name="`questions[${i}].type`" @change="feedback.changed(`questions[${i}].type`)"><option v-for="(label,key) in types" :key="key" :value="key">{{ label }}</option></select></label><label>展示顺序 <input v-model.number="q.sortOrder" :name="`questions[${i}].sortOrder`" type="number" min="0" max="9999" required :aria-invalid="fieldErrors[`questions[${i}].sortOrder`]?'true':undefined" :aria-describedby="`quiz-order-${i}-error`" @input="feedback.changed(`questions[${i}].sortOrder`)"><FieldError :id="`quiz-order-${i}-error`" :message="fieldErrors[`questions[${i}].sortOrder`]"/></label></div><div class="reading-field"><label :for="`quiz-stem-${i}`">第{{ i+1 }}题题干</label><textarea :id="`quiz-stem-${i}`" v-model="q.stem" :name="`questions[${i}].stem`" rows="2" required maxlength="2000" :aria-invalid="fieldErrors[`questions[${i}].stem`]?'true':undefined" :aria-describedby="`quiz-stem-${i}-error`" @input="feedback.changed(`questions[${i}].stem`)"/><FieldError :id="`quiz-stem-${i}-error`" :message="fieldErrors[`questions[${i}].stem`]"/></div><div v-for="(_,o) in q.options" :key="o" class="reading-field"><label :for="`quiz-option-${i}-${o}`">第{{ i+1 }}题选项{{ 'ABCD'[o] }}</label><input :id="`quiz-option-${i}-${o}`" v-model="q.options[o]" :name="`questions[${i}].options[${o}]`" required maxlength="1000" :aria-invalid="fieldErrors[`questions[${i}].options`]||fieldErrors[`questions[${i}].options[${o}]`]?'true':undefined" :aria-describedby="`quiz-option-${i}-${o}-error quiz-options-${i}-error`" @input="feedback.changed(`questions[${i}].options`);feedback.changed(`questions[${i}].options[${o}]`)"><FieldError :id="`quiz-option-${i}-${o}-error`" :message="fieldErrors[`questions[${i}].options[${o}]`]"/></div><FieldError :id="`quiz-options-${i}-error`" :message="fieldErrors[`questions[${i}].options`]"/><label>正确答案 <select v-model="q.correctOption" :name="`questions[${i}].correctOption`"><option v-for="letter in 'ABCD'" :key="letter" :value="letter">{{ letter }}</option></select></label><div class="reading-field"><label :for="`quiz-explanation-${i}`">第{{ i+1 }}题解析</label><textarea :id="`quiz-explanation-${i}`" v-model="q.explanation" :name="`questions[${i}].explanation`" rows="3" required maxlength="4000" :aria-invalid="fieldErrors[`questions[${i}].explanation`]?'true':undefined" :aria-describedby="`quiz-explanation-${i}-error`" @input="feedback.changed(`questions[${i}].explanation`)"/><FieldError :id="`quiz-explanation-${i}-error`" :message="fieldErrors[`questions[${i}].explanation`]"/></div></section><button type="button" class="button-secondary" :disabled="questions.length>=10" @click="add">添加题目（{{ questions.length }} / 10）</button></fieldset><FormFeedback ref="panel" :message="formError"/><button v-if="conflict" class="button-secondary" type="button" :disabled="busy" @click="reload">加载最新题组</button><div class="reading-actions"><button class="button-primary" :disabled="busy||sessionStale">{{ busy?'正在处理…':'保存题组草稿' }}</button><button v-if="record" class="button-secondary" type="button" :disabled="busy||dirty||sessionStale" @click="status(true)">{{ record.status==='PUBLISHED'?'发布题组更新':'发布题组' }}</button><button v-if="record?.status==='PUBLISHED'" class="button-secondary" type="button" :disabled="busy||dirty||sessionStale" @click="status(false)">下架题组</button></div><p class="field-hint">{{ dirty?'有未保存修改':'草稿已同步' }} · 发布前请校对内容，旧版本与体验不会被改写。</p></form></template><FormFeedback v-else-if="!loading&&!pageError" :message="formError"/></section></template>
